-- Final, idempotent Content Creator recruitment reconciliation.
-- Replays the production state after the historical 20260828145436..150508
-- migrations while preserving shared Sales/UIUX/Developer recruitment behavior.

DO $$
DECLARE v_job_id uuid;
BEGIN
  SELECT id INTO v_job_id
  FROM public.career_jobs
  WHERE slug='content-writer' AND application_type='content_writer'
  LIMIT 1;
  IF v_job_id IS NULL THEN
    RAISE EXCEPTION 'Content Creator career job was not found.';
  END IF;

  UPDATE public.career_jobs
  SET title='Content Creator',
      engagement_type='Independent Contractor / Project-Based',
      requires_intro_video=true,
      role_details=coalesce(role_details,'{}'::jsonb)
        || jsonb_build_object(
          'systemRole','content_writer',
          'department','Content',
          'trainingTrack','content_writer',
          'engagementModel','project_based_contractor',
          'portfolioTiming','post_screening',
          'portfolioMinimumCaseStudies',3,
          'practicalPassingScore',90,
          'agreementRequiredBeforeAcademy',true,
          'finalApprovalRequired',true,
          'systemAccessRequiredBeforeActivation',true,
          'applicationForm',coalesce(role_details->'applicationForm','{}'::jsonb)
            || jsonb_build_object('cvRequired',true,'portfolioRequired',false,'portfolioDeferred',true,'minimumWeeklyHours',coalesce((role_details->'applicationForm'->>'minimumWeeklyHours')::int,20))
        ),
      selection_process=jsonb_build_array(
        jsonb_build_object('title','Application','text','Submit your application with a current resume/CV and a short introduction video.'),
        jsonb_build_object('title','Video + Resume Review','text','We review communication, relevant experience, reliability and role fit.'),
        jsonb_build_object('title','Portfolio Review','text','Shortlisted candidates receive a secure link to submit at least three structured case studies.'),
        jsonb_build_object('title','Content Assessment','text','Complete the role-specific content assessment against the ProFox quality rubric.'),
        jsonb_build_object('title','Conditional Selected','text','Candidates who pass the assessment are conditionally selected, subject to agreement and certification.'),
        jsonb_build_object('title','Project-Based Agreement','text','Review and sign the approved project-based Content Creator agreement.'),
        jsonb_build_object('title','Content Academy','text','Complete the ProFox content operating model, PF-SOP-07 and niche/playbook learning.'),
        jsonb_build_object('title','Practical Certification','text','Submit a production-style practical. Independent review requires a minimum 90% score.'),
        jsonb_build_object('title','Final Approval','text','Management verifies all gates before production access can be approved.'),
        jsonb_build_object('title','System Access','text','Approved production access is provisioned before activation.'),
        jsonb_build_object('title','Activated','text','You become eligible for approved ProFox content projects and remain subject to independent quality review.')
      ),
      updated_at=now()
  WHERE id=v_job_id;

  UPDATE public.recruitment_stage_policies SET active=false,updated_at=now() WHERE job_id=v_job_id;

  UPDATE public.recruitment_stage_policies SET sort_order=1,active=true,assessment_required=false,passing_score=null,sla_hours=24,interview_required=false,rubric='[]'::jsonb,updated_at=now() WHERE job_id=v_job_id AND stage='New Application';
  IF NOT FOUND THEN INSERT INTO public.recruitment_stage_policies(job_id,stage,sort_order,active,assessment_required,passing_score,sla_hours,interview_required,rubric) VALUES(v_job_id,'New Application',1,true,false,null,24,false,'[]'::jsonb); END IF;

  UPDATE public.recruitment_stage_policies SET sort_order=2,active=true,assessment_required=true,passing_score=75,sla_hours=48,interview_required=false,rubric='[{"key":"communication","label":"Introduction video communication","maxPoints":25},{"key":"relevant_experience","label":"Relevant content experience","maxPoints":30},{"key":"resume_evidence","label":"Resume evidence and progression","maxPoints":20},{"key":"reliability_fit","label":"Reliability and role fit","maxPoints":25}]'::jsonb,updated_at=now() WHERE job_id=v_job_id AND stage='Video & Resume Review';
  IF NOT FOUND THEN INSERT INTO public.recruitment_stage_policies(job_id,stage,sort_order,active,assessment_required,passing_score,sla_hours,interview_required,rubric) VALUES(v_job_id,'Video & Resume Review',2,true,true,75,48,false,'[{"key":"communication","label":"Introduction video communication","maxPoints":25},{"key":"relevant_experience","label":"Relevant content experience","maxPoints":30},{"key":"resume_evidence","label":"Resume evidence and progression","maxPoints":20},{"key":"reliability_fit","label":"Reliability and role fit","maxPoints":25}]'::jsonb); END IF;

  UPDATE public.recruitment_stage_policies SET sort_order=3,active=true,assessment_required=true,passing_score=80,sla_hours=72,interview_required=false,rubric='[{"key":"clarity_structure","label":"Clarity and information structure","maxPoints":20},{"key":"commercial_quality","label":"Commercial / conversion quality","maxPoints":20},{"key":"research_evidence","label":"Research and evidence discipline","maxPoints":20},{"key":"originality_voice","label":"Originality and voice control","maxPoints":15},{"key":"outcomes","label":"Outcome / result awareness","maxPoints":15},{"key":"presentation","label":"Professional presentation","maxPoints":10}]'::jsonb,updated_at=now() WHERE job_id=v_job_id AND stage='Portfolio Review';
  IF NOT FOUND THEN INSERT INTO public.recruitment_stage_policies(job_id,stage,sort_order,active,assessment_required,passing_score,sla_hours,interview_required,rubric) VALUES(v_job_id,'Portfolio Review',3,true,true,80,72,false,'[{"key":"clarity_structure","label":"Clarity and information structure","maxPoints":20},{"key":"commercial_quality","label":"Commercial / conversion quality","maxPoints":20},{"key":"research_evidence","label":"Research and evidence discipline","maxPoints":20},{"key":"originality_voice","label":"Originality and voice control","maxPoints":15},{"key":"outcomes","label":"Outcome / result awareness","maxPoints":15},{"key":"presentation","label":"Professional presentation","maxPoints":10}]'::jsonb); END IF;

  UPDATE public.recruitment_stage_policies SET sort_order=4,active=true,assessment_required=true,passing_score=85,sla_hours=72,interview_required=false,rubric='[{"key":"user_need","label":"User-need alignment","maxPoints":20},{"key":"message_hierarchy","label":"Message hierarchy","maxPoints":20},{"key":"conversion","label":"Conversion thinking","maxPoints":20},{"key":"clarity","label":"Clarity and scannability","maxPoints":20},{"key":"brand_originality","label":"Brand fit, originality and truthfulness","maxPoints":20}]'::jsonb,updated_at=now() WHERE job_id=v_job_id AND stage='Content Assessment';
  IF NOT FOUND THEN INSERT INTO public.recruitment_stage_policies(job_id,stage,sort_order,active,assessment_required,passing_score,sla_hours,interview_required,rubric) VALUES(v_job_id,'Content Assessment',4,true,true,85,72,false,'[{"key":"user_need","label":"User-need alignment","maxPoints":20},{"key":"message_hierarchy","label":"Message hierarchy","maxPoints":20},{"key":"conversion","label":"Conversion thinking","maxPoints":20},{"key":"clarity","label":"Clarity and scannability","maxPoints":20},{"key":"brand_originality","label":"Brand fit, originality and truthfulness","maxPoints":20}]'::jsonb); END IF;

  UPDATE public.recruitment_stage_policies SET sort_order=5,active=true,assessment_required=false,passing_score=null,sla_hours=24,interview_required=false,rubric='[]'::jsonb,updated_at=now() WHERE job_id=v_job_id AND stage='Selected';
  IF NOT FOUND THEN INSERT INTO public.recruitment_stage_policies(job_id,stage,sort_order,active,assessment_required,passing_score,sla_hours,interview_required,rubric) VALUES(v_job_id,'Selected',5,true,false,null,24,false,'[]'::jsonb); END IF;
  UPDATE public.recruitment_stage_policies SET sort_order=6,active=true,assessment_required=false,passing_score=null,sla_hours=72,interview_required=false,rubric='[]'::jsonb,updated_at=now() WHERE job_id=v_job_id AND stage='Agreement Pending';
  IF NOT FOUND THEN INSERT INTO public.recruitment_stage_policies(job_id,stage,sort_order,active,assessment_required,passing_score,sla_hours,interview_required,rubric) VALUES(v_job_id,'Agreement Pending',6,true,false,null,72,false,'[]'::jsonb); END IF;
  UPDATE public.recruitment_stage_policies SET sort_order=7,active=true,assessment_required=false,passing_score=null,sla_hours=168,interview_required=false,rubric='[]'::jsonb,updated_at=now() WHERE job_id=v_job_id AND stage='Content Academy';
  IF NOT FOUND THEN INSERT INTO public.recruitment_stage_policies(job_id,stage,sort_order,active,assessment_required,passing_score,sla_hours,interview_required,rubric) VALUES(v_job_id,'Content Academy',7,true,false,null,168,false,'[]'::jsonb); END IF;
  UPDATE public.recruitment_stage_policies SET sort_order=8,active=true,assessment_required=false,passing_score=90,sla_hours=72,interview_required=false,rubric='[]'::jsonb,updated_at=now() WHERE job_id=v_job_id AND stage='Practical Certification';
  IF NOT FOUND THEN INSERT INTO public.recruitment_stage_policies(job_id,stage,sort_order,active,assessment_required,passing_score,sla_hours,interview_required,rubric) VALUES(v_job_id,'Practical Certification',8,true,false,90,72,false,'[]'::jsonb); END IF;
  UPDATE public.recruitment_stage_policies SET sort_order=9,active=true,assessment_required=false,passing_score=90,sla_hours=24,interview_required=false,rubric='[]'::jsonb,updated_at=now() WHERE job_id=v_job_id AND stage='Final Approval';
  IF NOT FOUND THEN INSERT INTO public.recruitment_stage_policies(job_id,stage,sort_order,active,assessment_required,passing_score,sla_hours,interview_required,rubric) VALUES(v_job_id,'Final Approval',9,true,false,90,24,false,'[]'::jsonb); END IF;
  UPDATE public.recruitment_stage_policies SET sort_order=10,active=true,assessment_required=false,passing_score=null,sla_hours=24,interview_required=false,rubric='[]'::jsonb,updated_at=now() WHERE job_id=v_job_id AND stage='Ready for System Access';
  IF NOT FOUND THEN INSERT INTO public.recruitment_stage_policies(job_id,stage,sort_order,active,assessment_required,passing_score,sla_hours,interview_required,rubric) VALUES(v_job_id,'Ready for System Access',10,true,false,null,24,false,'[]'::jsonb); END IF;
  UPDATE public.recruitment_stage_policies SET sort_order=11,active=true,assessment_required=false,passing_score=null,sla_hours=24,interview_required=false,rubric='[]'::jsonb,updated_at=now() WHERE job_id=v_job_id AND stage='Activated';
  IF NOT FOUND THEN INSERT INTO public.recruitment_stage_policies(job_id,stage,sort_order,active,assessment_required,passing_score,sla_hours,interview_required,rubric) VALUES(v_job_id,'Activated',11,true,false,null,24,false,'[]'::jsonb); END IF;
END $$;

UPDATE public.recruitment_task_templates
SET active=false,updated_at=now()
WHERE system_role='content_writer' AND stage='Portfolio Review' AND task_key<>'content_writer_portfolio_v2';
UPDATE public.recruitment_task_templates
SET title='Content Creator Portfolio - 3 Case Studies',
    description='Submit three structured examples that show what you wrote, why you made the decisions you made, and the business/user outcome. Do not submit confidential client material.',
    target_market='International',target_niche='Multi-industry',required_items=3,deadline_hours=72,estimated_minutes=60,max_attempts=2,
    instructions='["Submit three or more structured case studies. For each case include project/title, industry/niche, content type/channel, brief/problem, your exact contribution, research/process, sample URL or permitted evidence, and result/outcome.","Identify your contribution honestly. If work was collaborative, state exactly which portions you personally produced or owned.","Protect confidential information. Use public links or authorized samples. Never submit private client credentials, personal data or confidential material.","Choose work that represents your current standard. We review clarity, commercial thinking, evidence discipline, originality, outcomes and presentation."]'::jsonb,
    active=true,updated_at=now()
WHERE task_key='content_writer_portfolio_v2' AND system_role='content_writer' AND stage='Portfolio Review';
INSERT INTO public.recruitment_task_templates(task_key,system_role,stage,title,description,target_market,target_niche,required_items,deadline_hours,estimated_minutes,max_attempts,instructions,version,active)
SELECT 'content_writer_portfolio_v2','content_writer','Portfolio Review','Content Creator Portfolio - 3 Case Studies','Submit three structured examples that show what you wrote, why you made the decisions you made, and the business/user outcome. Do not submit confidential client material.','International','Multi-industry',3,72,60,2,'["Submit three or more structured case studies. For each case include project/title, industry/niche, content type/channel, brief/problem, your exact contribution, research/process, sample URL or permitted evidence, and result/outcome.","Identify your contribution honestly. If work was collaborative, state exactly which portions you personally produced or owned.","Protect confidential information. Use public links or authorized samples. Never submit private client credentials, personal data or confidential material.","Choose work that represents your current standard. We review clarity, commercial thinking, evidence discipline, originality, outcomes and presentation."]'::jsonb,2,true
WHERE NOT EXISTS(SELECT 1 FROM public.recruitment_task_templates WHERE task_key='content_writer_portfolio_v2' AND system_role='content_writer' AND stage='Portfolio Review');

UPDATE public.sales_agreement_templates
SET status='Published',title='ProFox Project-Based Content Creator Agreement',subtitle='Independent contractor engagement for approved content projects',
    introduction='This agreement governs project-based content services. It does not create a salaried employment relationship, partnership or authority to bind ProFox.',
    sections='[{"title":"Independent project-based relationship","body":"The Content Creator provides services as an independent contractor on projects separately assigned and accepted. No minimum volume of projects, monthly salary or guaranteed earnings are promised by this agreement."},{"title":"Project scope and commercial terms","body":"Each approved project or work order controls its scope, deliverables, timeline, fee, revision allowance and acceptance requirements. Work outside the approved scope requires written authorization."},{"title":"ProFox quality system","body":"The contractor must follow the current Content Academy standards, PF-SOP-07, client truth/evidence rules, applicable niche playbooks, review requirements and secure UI/UX handoff process."},{"title":"Confidentiality, data and security","body":"Client and ProFox information must be used only for authorized work, protected from unauthorized access, and returned or deleted when required."},{"title":"Originality and intellectual property","body":"Deliverables must be original, lawful and properly licensed. Rights transfer is governed by the applicable project and client terms; pre-existing tools remain subject to disclosed licenses."},{"title":"Accuracy and prohibited conduct","body":"The contractor must not fabricate facts, testimonials, research, results or client claims; plagiarize; use unapproved confidential material; or make representations on behalf of ProFox beyond written authority."},{"title":"Review, revisions and production access","body":"Independent quality review is mandatory. Production/client access is granted only after Academy completion, Practical Certification at 90% or higher, Final Approval and System Access authorization."},{"title":"Termination and surviving duties","body":"Either party may end the engagement subject to active project obligations and applicable law. Confidentiality, data-return/deletion, intellectual-property and accrued payment obligations survive where applicable."}]'::jsonb,
    acknowledgements='[{"key":"independent_contractor","label":"I understand this is a project-based independent contractor arrangement and not a guaranteed salaried position."},{"key":"quality_sop","label":"I agree to follow ProFox content SOPs, evidence standards, review and handoff requirements."},{"key":"confidentiality","label":"I agree to protect ProFox and client confidential information and data."},{"key":"truth_originality","label":"I will not fabricate claims, plagiarize, or misrepresent authorship, research or results."}]'::jsonb,
    agreement_type='content_writer',target_role='content_writer',published_at=coalesce(published_at,now()),updated_at=now()
WHERE template_key='content_creator_project_contractor' AND version=1;
