('content_recruitment_practical_submitted','Content practical submitted','Your ProFox Practical Certification is under review','Hi {{candidateName}},\n\nWe have received your Content Creator Practical Certification submission. It is now locked for independent review against PF-SOP-07 and the current quality standard.\n\nA passing score of 90% or higher is required.\n\nRegards,\nProFox Recruitment Team',null,true,'Candidate confirmation after Content practical submission.'),
('content_recruitment_practical_passed','Content practical passed','You passed ProFox Practical Certification','Hi {{candidateName}},\n\nCongratulations. Your Content Creator Practical Certification has passed independent review at the required standard.\n\nYour application is now in Final Approval. Production access is still locked until Management completes Final Approval and System Access authorization.\n\nRegards,\nProFox Recruitment Team',null,true,'Candidate notice after practical certification passes.'),
('content_recruitment_practical_retry','Content practical retry','Action required: revise your ProFox Practical Certification','Hi {{candidateName}},\n\nYour Practical Certification needs revision before it can pass. Please review the feedback in your Academy workspace, update the required areas, and resubmit through the controlled certification workflow.\n\nRegards,\nProFox Recruitment Team',null,true,'Candidate practical retry notification.'),
('content_recruitment_final_approved','Content final approval','Final Approval complete - system access is next','Hi {{candidateName}},\n\nYour Content Creator Final Approval is complete. Your candidate record is now at Ready for System Access.\n\nThe ProFox team will confirm your production access before activation.\n\nRegards,\nProFox Recruitment Team',null,true,'Candidate Final Approval and System Access notification.')
